import{_ as t,o as a,c as i,aG as s}from"./chunks/framework.C0GbWxTg.js";const u=JSON.parse('{"title":"predicates (internal)","description":"Checks shared by the package, active in production.","frontmatter":{"title":"predicates (internal)","description":"Checks shared by the package, active in production."},"headers":[],"relativePath":"packages/common-authorization/utilities/predicates.md","filePath":"packages/common-authorization/utilities/predicates.md"}'),r={name:"packages/common-authorization/utilities/predicates.md"};function o(n,e,d,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="predicates" tabindex="-1">predicates <a class="header-anchor" href="#predicates" aria-label="Permalink to &quot;predicates&quot;">​</a></h1><p>Checks shared by <a href="./../runtime/authorization.html">Authorization</a> and <a href="./abilities.html">abilities</a>. Unlike assertions, they remain active in production, as their violation would make an authorization decision unreliable.</p><p>The module is internal to the package: it is not exported.</p><h2 id="ensuresynchronous" tabindex="-1">ensureSynchronous <a class="header-anchor" href="#ensuresynchronous" aria-label="Permalink to &quot;ensureSynchronous&quot;">​</a></h2><h3 id="signature" tabindex="-1">Signature <a class="header-anchor" href="#signature" aria-label="Permalink to &quot;Signature&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ensureSynchronous</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(value, message)</span></span></code></pre></div><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Ensures that the value returned by a function supplied to the package is not a promise. Rules must all be defined before the ability is built: an asynchronous function would complete afterwards, silently leaving the ability incomplete or unscoped.</p><p>Any value with a <code>then</code> method is treated as a promise, including the result of an <code>async</code> function.</p><p>The function has already run when its result is checked. When the result is a promise, a handler is attached to it before the error is thrown, so that its rejection is not left unhandled. The rejection itself is discarded: the <code>TypeError</code> is the only error reported.</p><p>The package checks the values returned by:</p><table tabindex="0"><thead><tr><th>Function</th><th>Message</th></tr></thead><tbody><tr><td>Authorization hooks</td><td><code>hook &lt;name&gt; must be synchronous</code></td></tr><tr><td>Role definitions supplied to <a href="./abilities.html#defineroleabilities">defineRoleAbilities</a></td><td><code>definition of role &lt;role&gt; must be synchronous</code></td></tr><tr><td>Scope functions supplied to <a href="./abilities.html#defineroleabilities">defineRoleAbilities</a></td><td><code>scope must be synchronous</code></td></tr></tbody></table><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>any</code></td><td>yes</td><td>Value returned by the function</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>yes</td><td>Error message when the value is a promise</td></tr></tbody></table><h3 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>any</code></td><td>The value, when it is not a promise</td></tr></tbody></table><h3 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to &quot;Throws&quot;">​</a></h3><p>Throws a <code>TypeError</code> with the given message if the value is a promise, in production too.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> conditions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ensureSynchronous</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rule), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;scope must be synchronous&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div>',20)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
